<?php
/** Slice 4 proof — tags (spec "Proof" 1, 2, 4): create managed and free, slugs, apply and remove with counts, bulk with a skip, archive/restore/delete rules, auto-tag rules on upload. */
require __DIR__ . '/lib.php';
$s = seed_texts();
$acme = $s['board_doc']; $minutes = $s['minutes']; $handbook = $s['handbook']; $priya = $s['priya_doc'];

echo "1. Making tags\n";
$r = post_j(27, '/tags/save.php', ['label' => 'Contract', 'kind' => 'managed', 'colour' => '#3454d1']);
ok($r['code'] === 200 && ($r['json']['slug'] ?? '') === 'contract' && ($r['json']['kind'] ?? '') === 'managed' && str_contains($r['json']['location'] ?? '', '/tags/' . $r['json']['record_id']), 'a curator makes a managed tag: slug contract, lands on the tag');
$contract = (int) $r['json']['record_id'];
ok(last_event('tag.create') !== null && (int) last_event('tag.create')['entity_id'] === $contract, 'logged tag.create');
$r = post_j(26, '/tags/save.php', ['label' => 'Acme Corp.', 'kind' => 'managed']);
ok($r['code'] === 403, 'a member may not make a managed tag (403)');
$r = post_j(26, '/tags/save.php', ['label' => 'Acme Corp.']);
ok($r['code'] === 200 && ($r['json']['slug'] ?? '') === 'acme-corp' && ($r['json']['kind'] ?? '') === 'free', 'a member makes a free tag: "Acme Corp." → acme-corp');
$acmeTag = (int) $r['json']['record_id'];
$r = post_j(26, '/tags/save.php', ['label' => 'Événement spécial']);
ok($r['code'] === 200 && ($r['json']['slug'] ?? '') === 'evenement-special', 'accents fall away in the slug');
$r = post_j(26, '/tags/save.php', ['label' => 'ACME CORP']);
ok($r['code'] === 200 && (int) $r['json']['record_id'] === $acmeTag && !empty($r['json']['existed']), 'a duplicate label resolves to the existing tag (existed)');
$r = post_j(26, '/tags/save.php', ['label' => '!!!']);
ok($r['code'] === 422, 'a label with no letter or digit is refused');
$r = post_j(26, '/tags/save.php', ['label' => str_repeat('x', 51)]);
ok($r['code'] === 422 && ($r['json']['error']['fields']['label'] ?? '') !== '', 'a label over 50 characters: 422 on the field');
$r = post_j(27, '/tags/save.php', ['label' => 'Board', 'kind' => 'managed', 'colour' => 'blue']);
ok($r['code'] === 422 && ($r['json']['error']['fields']['colour'] ?? '') !== '', 'a colour is a hex value: "blue" is refused on the field');
post_j(27, '/tags/save.php', ['label' => 'Board', 'kind' => 'managed']);
$board = tag_id('board');

echo "2. Applying and removing\n";
$r = post_j(27, '/tags/apply.php', ['document' => $acme, 'tags' => ['contract']]);
ok($r['code'] === 200 && ($r['json']['applied'] ?? 0) === 1 && tags_of($acme) === ['contract'] && (int) one('SELECT usage_count FROM tags WHERE id = :id', ['id' => $contract]) === 1, 'the owner tags a document by slug: applied 1, counted');
ok(str_ends_with($r['json']['location'] ?? '', '/documents/' . $acme . '?notice=tagged#document-tags'), '…lands on the document at the tags');
$r = post_j(27, '/tags/apply.php', ['document' => $acme, 'tags' => ['Contract']]);
ok($r['code'] === 200 && ($r['json']['applied'] ?? 1) === 0 && ($r['json']['already'] ?? 0) === 1 && (int) one('SELECT usage_count FROM tags WHERE id = :id', ['id' => $contract]) === 1, 'applied once counts once (already 1, the count unchanged)');
$ev = last_event('tag.apply');
ok($ev !== null && (int) $ev['document_id'] === $acme && json_decode($ev['after'], true)['tag'] === 'contract', 'logged tag.apply with the document and the slug');
$r = post_j(26, '/tags/apply.php', ['document' => $acme, 'tags' => ['New Label Here']]);
ok($r['code'] === 200 && in_array('new-label-here', tags_of($acme), true) && tag_row('new-label-here')['kind'] === 'free', 'a group member (edit) types a new label on a document: a free tag with the design\'s slug');
$r = post_j(28, '/tags/apply.php', ['document' => $acme, 'tags' => ['contract']]);
ok($r['code'] === 404, 'a member outside the group: 404 (the same nothing)');
pdo()->exec("INSERT INTO folder_access (folder_id, principal_kind, principal_id, level, granted_by) VALUES ({$s['contracts']}, 'member', 28, 'view', 27) ON CONFLICT DO NOTHING");
$r = post_j(28, '/tags/apply.php', ['document' => $acme, 'tags' => ['contract']]);
ok($r['code'] === 403, 'a viewer by row sees the chips and may not change them (403)');
$r = post_j(29, '/tags/apply.php', ['document' => $s['guest_doc'], 'tags' => ['contract']]);
ok($r['code'] === 403, 'a guest holds no tags.apply');
$r = post_j(27, '/tags/remove.php', ['document' => $acme, 'tags' => ['new-label-here']]);
ok($r['code'] === 200 && ($r['json']['removed'] ?? []) === ['new-label-here'] && !in_array('new-label-here', tags_of($acme), true) && (int) one("SELECT usage_count FROM tags WHERE slug = 'new-label-here'") === 0, 'a removal recounts');
ok(last_event('tag.remove') !== null, 'logged tag.remove');
$r = post_j(27, '/tags/remove.php', ['document' => $acme, 'tags' => ['never-there']]);
ok($r['code'] === 200 && ($r['json']['removed'] ?? ['x']) === [], 'removing a tag that is not there is nothing');

echo "3. Bulk from a listing\n";
$r = post_j(26, '/tags/apply.php', ['documents' => [$acme, $minutes, $handbook], 'tags' => ['board']]);
ok($r['code'] === 200 && ($r['json']['applied'] ?? 0) === 2 && ($r['json']['skipped'] ?? 0) === 1 && in_array('board', tags_of($acme), true) && in_array('board', tags_of($minutes), true) && !in_array('board', tags_of($handbook), true), 'bulk apply to three where one is view-only: applied 2, skipped 1');
ok(str_contains($r['json']['did'] ?? '', '1 skipped'), '…and the answer says so');
$r = post_j(26, '/tags/apply.php', ['documents' => [$handbook], 'tags' => ['board']]);
ok($r['code'] === 403, 'one document the caller may only view: 403, not a silent skip');

echo "4. Archive, restore, delete\n";
$r = post_j(26, '/tags/archive.php', ['tag' => $board]);
ok($r['code'] === 403, 'a member may not archive (tags.manage)');
$r = post_j(27, '/tags/archive.php', ['tag' => $board]);
ok($r['code'] === 200 && one('SELECT archived_at FROM tags WHERE id = :id', ['id' => $board]) !== null && in_array('board', tags_of($acme), true), 'archived: it stays on its documents');
$pick = get_json(27, '/pick/?source=tag&q=board')['json'];
ok(!str_contains(json_encode($pick), '"' . $board . '"') || !str_contains(json_encode($pick), 'Board'), '…and is hidden from the picker');
$r = post_j(27, '/tags/delete.php', ['tag' => $board]);
ok($r['code'] === 422 && str_contains($r['json']['error']['message'] ?? $r['body'], 'archive it instead'), 'a tag in use is never deleted: 422 in words');
$r = post_j(27, '/tags/restore.php', ['tag' => $board]);
ok($r['code'] === 200 && one('SELECT archived_at FROM tags WHERE id = :id', ['id' => $board]) === null, 'restored');
$r = post_j(27, '/tags/save.php', ['label' => 'Throwaway', 'kind' => 'managed']);
$throw = (int) $r['json']['record_id'];
$r = post_j(27, '/tags/delete.php', ['tag' => $throw]);
ok($r['code'] === 200 && one('SELECT count(*) FROM tags WHERE id = :id', ['id' => $throw]) === 0 && last_event('tag.delete') !== null, 'an unused tag is deleted; logged');
$r = post_j(27, '/tags/save.php', ['tag' => $contract, 'label' => 'Contracts', 'colour' => '#10b981']);
ok($r['code'] === 200 && one('SELECT label FROM tags WHERE id = :id', ['id' => $contract]) === 'Contracts' && one('SELECT slug FROM tags WHERE id = :id', ['id' => $contract]) === 'contract' && one('SELECT colour FROM tags WHERE id = :id', ['id' => $contract]) === '#10b981', 'tag_update relabels and recolours; the slug never changes');
ok(last_event('tag.update') !== null && json_decode(last_event('tag.update')['before'], true)['label'] === 'Contract', 'logged tag.update with before/after');

echo "5. Auto-tag rules\n";
$r = post_j(27, '/folders/auto-tags.php', ['folder' => $s['contracts'], 'auto_tags' => ['contract', 'Twenty Twenty-Six']]);
ok($r['code'] === 200 && ($r['json']['auto_tags'] ?? []) === ['contract', 'twenty-twenty-six'], 'a folder\'s auto-tags: slugs resolved or made');
$up = upload_file(27, $s['contracts'], tmpfile_of(3000, 'auto', 'auto-rule.pdf'));
$autoDoc = (int) ($up['finish']['json']['record_id'] ?? 0);
ok($autoDoc > 0 && tags_of($autoDoc) === ['contract', 'twenty-twenty-six'] && one("SELECT source FROM document_tags WHERE document_id = :d AND tag_id = :t", ['d' => $autoDoc, 't' => $contract]) === 'rule', 'a new upload under the folder carries the rule\'s tags, source rule');
pdo()->exec("INSERT INTO folders (library_id, parent_id, name, owner_member_id, created_by) VALUES ((SELECT library_id FROM folders WHERE id = {$s['contracts']}), {$s['contracts']}, 'Deeper', 27, 27) ON CONFLICT DO NOTHING");
$deeper = (int) one("SELECT id FROM folders WHERE parent_id = :p AND name = 'Deeper'", ['p' => $s['contracts']]);
post_j(27, '/folders/auto-tags.php', ['folder' => $deeper, 'auto_tags' => ['board']]);
$up2 = upload_file(27, $deeper, tmpfile_of(2000, 'deep', 'deep-rule.pdf'));
$deepDoc = (int) ($up2['finish']['json']['record_id'] ?? 0);
ok($deepDoc > 0 && tags_of($deepDoc) === ['board'], 'a deeper folder\'s rule wins over the parent\'s');
$r = page(actor(27), '/f/' . $s['contracts']);
ok($r['code'] === 200 && str_contains($r['body'], 'id="folder-auto-tags"') && str_contains($r['body'], '>contract<') && str_contains($r['body'], 'id="folder-auto-tags-link"'), 'the folder page shows the rule as chips with a link to change it');
$r = page(actor(27), '/tags/rules');
ok($r['code'] === 200 && str_contains($r['body'], 'id="tag-rule-' . $s['contracts'] . '"') && str_contains($r['body'], 'id="tag-rule-' . $deeper . '"'), 'the rules screen lists both folders');
$r = page(actor(27), '/tags/rules?folder=' . $deeper);
ok($r['code'] === 200 && str_contains($r['body'], 'id="tag-rule-form"') && str_contains($r['body'], 'value="board"'), '…a folder\'s own rule form');

echo "6. The screens\n";
$r = page(actor(26), '/tags');
ok($r['code'] === 200 && str_contains($r['body'], 'id="tag-chip-' . $contract . '"') && str_contains($r['body'], 'id="tag-chip-' . $acmeTag . '"') && !str_contains($r['body'], 'id="tag-new-btn"') && !str_contains($r['body'], 'id="proposals-card"'), 'the tags page for a member: chips, no New tag, no proposals');
$r = page(actor(27), '/tags');
ok($r['code'] === 200 && str_contains($r['body'], 'id="tag-new-btn"'), '…a curator gets New tag');
$r = page(actor(27), '/tags?kind=free');
ok($r['code'] === 200 && !str_contains($r['body'], 'id="tag-chip-' . $contract . '"') && str_contains($r['body'], 'id="tag-chip-' . $acmeTag . '"'), 'the kind filter');
$r = page(actor(27), '/tags/' . $contract);
ok($r['code'] === 200 && str_contains($r['body'], 'id="tag-documents-list"') && str_contains($r['body'], 'id="search-result-' . $acme . '"') && str_contains($r['body'], 'id="tag-edit-btn"'), 'a tag\'s page lists its documents through the wall');
$r = page(actor(28), '/tags/' . $contract);
ok($r['code'] === 200 && str_contains($r['body'], 'id="search-result-' . $acme . '"') && str_contains($r['body'], 'id="search-result-' . $autoDoc . '"') && !str_contains($r['body'], 'id="search-result-' . $deepDoc . '"') && !str_contains($r['body'], 'id="tag-edit-btn"'), '…Bea (a viewer of Contracts by row) sees acme and the rule\'s upload there, not Deeper\'s (board, not contract); no Edit');
$r = page(actor(26), '/tags/' . $contract);
ok($r['code'] === 200 && str_contains($r['body'], 'id="search-result-' . $acme . '"'), 'a group member sees the group\'s documents on the tag page');
$r = page(actor(29), '/tags');
ok($r['code'] === 403, 'a guest holds no tags.apply: the tags page is 403');
$r = page(actor(27), '/tags/' . $contract . '/edit');
ok($r['code'] === 200 && str_contains($r['body'], 'id="tag-form"') && str_contains($r['body'], 'id="tag-merge-form"') && str_contains($r['body'], 'id="tag-merge-into-picker"'), 'the edit form with the merge picker');
$r = page(actor(26), '/tags/' . $contract . '/edit');
ok($r['code'] === 403, 'a member may not edit a tag');
$r = page(actor(27), '/documents/' . $acme);
ok($r['code'] === 200 && str_contains($r['body'], 'id="tag-editor"') && str_contains($r['body'], 'id="tag-input"') && str_contains($r['body'], 'id="tag-chip-' . $contract . '"') && str_contains($r['body'], 'id="tag-remove-' . $contract . '"') && str_contains($r['body'], 'id="tag-vocabulary"'), 'the document page: the editor with chips, the × and the datalist');
$r = page(actor(28), '/documents/' . $acme);
ok($r['code'] === 200 && str_contains($r['body'], 'id="tag-chip-' . $contract . '"') && !str_contains($r['body'], 'id="tag-input"') && !str_contains($r['body'], 'id="tag-remove-' . $contract . '"'), '…a viewer sees the chips and no editor');
$r = page(actor(27), '/f/' . $s['contracts']);
ok($r['code'] === 200 && str_contains($r['body'], 'id="select-bar-tag-input"') && str_contains($r['body'], 'name="documents[]"'), 'the listing\'s select bar gains Tag and the documents gain a checkbox');
$j = get_json(27, '/tags')['json']['data'] ?? [];
ok(count($j['tags'] ?? []) >= 3 && isset($j['tags'][0]['slug']) && !isset($j['tags'][0]['created_by_email']), 'the tags page answers JSON (the presenter)');
$j = get_json(27, '/documents/' . $acme)['json']['data'] ?? [];
ok(is_array($j['tags'] ?? null) && in_array('contract', array_column($j['tags'], 'slug'), true), 'the document page\'s JSON carries the tags with ids');
finish();
